254: /** Pure validator for the frozen strict JSON subset; no I/O or stateful dependency. */
255: export function validateStaticJsonSchema(value: unknown, schema: StaticJsonSchema, path = "$"): string[] {
256:   const errors: string[] = [];
257:   const supported = new Set(["$schema", "$id", "title", "description", "type", "enum", "required", "properties", "additionalProperties", "items", "minimum", "maximum", "minItems", "maxItems", "minLength", "maxLength"]);
258:   const inspectRule = (rule: StaticJsonSchema): void => {
259:     for (const keyword of Object.keys(rule)) if (!supported.has(keyword)) throw new Error(`graph-schema: unsupported keyword ${keyword}`);
260:     for (const child of Object.values(rule.properties ?? {})) inspectRule(child);
261:     if (rule.items) inspectRule(rule.items);
262:   };
263:   inspectRule(schema);
264:   const visit = (input: unknown, rule: StaticJsonSchema, at: string): void => {
265:     const actual = input === null ? "null" : Array.isArray(input) ? "array" : typeof input === "number" && Number.isInteger(input) ? "integer" : typeof input;
266:     const types = Array.isArray(rule.type) ? rule.type : [rule.type];
267:     if (!types.includes(actual) && !(actual === "integer" && types.includes("number"))) { errors.push(`${at}: invalid type ${actual}`); return; }
268:     if (rule.enum && !rule.enum.some(v => canonical(v) === canonical(input))) errors.push(`${at}: enum violation`);
269:     if (typeof input === "number") {
270:       if (!Number.isFinite(input)) errors.push(`${at}: non-finite number`);
271:       if (Object.is(input, -0)) errors.push(`${at}: non-canonical negative zero`);
272:       if (actual === "integer" && !Number.isSafeInteger(input)) errors.push(`${at}: unsafe integer`);
273:       if (rule.minimum !== undefined && input < rule.minimum) errors.push(`${at}: minimum violation`);
274:       if (rule.maximum !== undefined && input > rule.maximum) errors.push(`${at}: maximum violation`);
275:     }
276:     if (typeof input === "string") {
277:       const length = [...input].length;
278:       if (rule.minLength !== undefined && length < rule.minLength) errors.push(`${at}: minLength violation`);
279:       if (rule.maxLength !== undefined && length > rule.maxLength) errors.push(`${at}: maxLength violation`);
280:     }
281:     if (Array.isArray(input)) {
282:       if (rule.minItems !== undefined && input.length < rule.minItems) errors.push(`${at}: minItems violation`);
283:       if (rule.maxItems !== undefined && input.length > rule.maxItems) errors.push(`${at}: maxItems violation`);
284:       if (rule.items) for (let i = 0; i < input.length; i++) visit(input[i], rule.items, `${at}[${i}]`);
285:     } else if (isObject(input)) {
286:       for (const field of rule.required ?? []) if (!Object.hasOwn(input, field)) errors.push(`${at}.${field}: required`);
287:       for (const [field, item] of Object.entries(input)) {
288:         const child = rule.properties?.[field];
289:         if (child) visit(item, child, `${at}.${field}`);
290:         else if (rule.additionalProperties === false) errors.push(`${at}.${field}: additionalProperties forbidden`);
291:       }
292:     }
293:   };
294:   visit(value, schema, path);
295:   return errors;
296: }
