43: function requireUnique<T extends { id: string }>(items: T[], kind: string): { unique: T[]; duplicates: number } {
44:   const byId = new Map<string, T>();
45:   let duplicates = 0;
46:   for (const item of items) {
47:     const previous = byId.get(item.id);
48:     if (previous === undefined) byId.set(item.id, item);
49:     else if (canonical(previous) !== canonical(item)) throw new Error(`graph-normalize: conflicting ${kind} id ${item.id}`);
50:     else duplicates += 1;
51:   }
52:   return { unique: [...byId.values()], duplicates };
53: }
